s.c:
SELECT name AS student_name,
       grade + 5 AS grade_with_bonus
FROM students;

SELECT * FROM products
WHERE category = 'tech'
  AND (price < 100 OR stock = 0);

SELECT * FROM students WHERE NOT city = 'Cairo';

SELECT name FROM students
WHERE age > 19
ORDER BY age;

SELECT * FROM products
ORDER BY price DESC
LIMIT 3;

SELECT * FROM products
ORDER BY id
LIMIT 2 OFFSET 2;

SELECT name FROM students WHERE name LIKE '%a';
SELECT name FROM students WHERE name LIKE '%ar%';
SELECT name FROM students WHERE name NOT LIKE 'A%';

SELECT name,
  CASE WHEN grade IS NULL THEN 'no grade' ELSE 'has grade' END AS status
FROM students;

UPDATE students
SET city = 'Alex'
WHERE id = 1;

-- DANGER: changes every row
-- UPDATE students SET city = 'Cairo';

-- Safe habit: test first
SELECT * FROM students WHERE id = 1;

SELECT COUNT(*) AS total_students,
       COUNT(grade) AS with_grade
FROM students;

SELECT SUM(stock) AS total_stock,
       AVG(price) AS avg_price
FROM products;

SELECT city, COUNT(*) AS students_count
FROM students
GROUP BY city;

-- Wrong in most systems:
-- SELECT city, name, COUNT(*) FROM students GROUP BY city;

-- Right:
SELECT city, COUNT(*) FROM students GROUP BY city;

SELECT SUBSTR('Hello World', 1, 5) AS part,
       REPLACE('a-b-c', '-', '+') AS replaced,
       TRIM('   hi   ') AS trimmed;

SELECT ROUND(3.14159, 2) AS r,
       ROUND(2.5) AS r0,
       ABS(-7) AS a;

SELECT id, id % 2 AS remainder
FROM students;

SELECT 7 / 2 AS int_div, 7 / 2.0 AS real_div;

