SELECT CAST(4.9 AS INTEGER) AS truncated;

CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  customer TEXT,
  created DATE
);
INSERT INTO orders VALUES
  (1, 'Ali', '2026-01-15'),
  (2, 'Sara', '2026-02-03'),
  (3, 'Omar', '2026-02-20');

SELECT * FROM orders
WHERE created >= '2026-02-01'
  AND created < '2026-03-01';

-- SQLite
SELECT strftime('%m', created) AS month, COUNT(*) AS n
FROM orders
GROUP BY month;

-- MySQL: SELECT MONTH(created), COUNT(*) FROM orders GROUP BY MONTH(created);

CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  username TEXT UNIQUE
);

CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  balance DECIMAL(10,2) CHECK (balance >= 0),
  age INTEGER CHECK (age BETWEEN 13 AND 120)
);

